using System;
using System.IO;
using System.Linq;
using System.Collections;
using UnityEngine;
using LighFight.Runtime;
// Isolated diagnostic. Original-body authority + original-native versus SDK fingers only.
[DefaultExecutionOrder(10000)]
public sealed class IslandFistEOFProbe:MonoBehaviour {
 public GameObject rawModel,targetModel;public RuntimeAnimatorController originalController;public NativeSupportPoseData pose;public NativeFingerPose sdk,native;public Material reviewMaterial;public bool[] bodyVertices;
 GameObject raw,ns,ss;Animator oracle;SkinnedMeshRenderer[] skins;Transform[][] bound,fingers;Mesh[] baked;StreamWriter log;string output;int failures;float maxEOF,maxBody,maxSource;bool captured;IDisposable lease;
 IEnumerator Start(){
  var args=Environment.GetCommandLineArgs();int ai=Array.IndexOf(args,"-islandFistOutput");output=ai>=0&&ai+1<args.Length?args[ai+1]:Path.Combine(Application.persistentDataPath,"IslandFistEOF");Directory.CreateDirectory(output);log=new StreamWriter(Path.Combine(output,"eof.csv"));log.WriteLine("seconds,coreTicks,variant,EOFVertexDrift,bodyDifferenceFromOriginal");
  raw=Instantiate(rawModel);ns=Instantiate(targetModel);ss=Instantiate(targetModel);var actors=new[]{raw,ns,ss};skins=actors.Select(x=>x.GetComponentInChildren<SkinnedMeshRenderer>()).ToArray();baked=actors.Select(x=>new Mesh()).ToArray();foreach(var actor in actors){foreach(var a in actor.GetComponentsInChildren<Animator>())a.enabled=false;if(reviewMaterial)foreach(var r in actor.GetComponentsInChildren<SkinnedMeshRenderer>())r.sharedMaterials=r.sharedMaterials.Select(x=>reviewMaterial).ToArray();}
  oracle=raw.GetComponent<Animator>();oracle.runtimeAnimatorController=originalController;oracle.applyRootMotion=false;oracle.cullingMode=AnimatorCullingMode.AlwaysAnimate;oracle.enabled=true;oracle.Rebind();oracle.enabled=false;bound=new[]{pose.Bind(ns.transform),pose.Bind(ss.transform)};fingers=new[]{native.joints.Select(j=>ns.transform.Find(j.path)).ToArray(),sdk.joints.Select(j=>ss.transform.Find(j.path)).ToArray()};
  lease=pose.PinAndPrewarm();{int count=Mathf.CeilToInt(pose.duration*240);for(int i=0;i<=count;){int ticks=Mathf.Min(i%2==0?3:1,count-i+1);float t=0;for(int k=0;k<ticks;k++,i++){t=Mathf.Min(i/240f,pose.duration);Apply(t);}var before=Vertices();yield return new WaitForEndOfFrame();var after=Vertices();Check(t,ticks,before,after);if(!captured&&t>=native.sourceSeconds){Capture(native.sourceSeconds);captured=true;}}}
  lease.Dispose();lease=null;log.Dispose();log=null;File.WriteAllText(Path.Combine(output,"verdict.txt"),"failures="+failures+"\nmaxEOF="+maxEOF+"\nmaxBodyDifference="+maxBody+"\nmaxSourceBodyDifference="+maxSource+"\nNative/SDK fingers ONLY. Images/hand surface witnesses require visual/contact review. No gameplay/closed-fist acceptance.\n");Debug.Log("ISLAND_FIST_EOF failures="+failures+" max="+maxEOF);Application.Quit(failures==0?0:1);
 }
 void Apply(float t){oracle.enabled=true;oracle.Play(pose.sourceName,0,Mathf.Min(t/pose.duration,.9999999f));oracle.Update(0);oracle.enabled=false;for(int i=0;i<2;i++){pose.Apply(bound[i],t);var fp=i==0?native:sdk;for(int j=0;j<30;j++)fingers[i][j].localRotation=fp.joints[j].rotation;}}
 Vector3[][] Vertices(){var result=new Vector3[3][];for(int a=0;a<3;a++){skins[a].BakeMesh(baked[a],true);result[a]=baked[a].vertices.Select(v=>skins[a].transform.TransformPoint(v)).ToArray();}return result;}
 void Check(float t,int ticks,Vector3[][] before,Vector3[][] after){for(int a=1;a<3;a++){float drift=0,body=0;for(int i=0;i<before[a].Length;i++){drift=Mathf.Max(drift,Vector3.Distance(before[a][i],after[a][i]));if(bodyVertices[i])body=Mathf.Max(body,Vector3.Distance(after[0][i],after[a][i]));}if(!float.IsFinite(drift)||!float.IsFinite(body)||drift>.00001f||body>.00001f)failures++;maxEOF=Mathf.Max(maxEOF,drift);maxBody=Mathf.Max(maxBody,body);maxSource=Mathf.Max(maxSource,body);log.WriteLine(FormattableString.Invariant($"{t:R},{ticks},{(a==1?"native":"SDK")},{drift:R},{body:R}"));}}
 void Capture(float exactTime){
  // Exact chosen sample, rather than nearest frame; same frozen body for every A/B image.
  Apply(exactTime);var vertices=Vertices();for(int a=0;a<3;a++){using(var w=new StreamWriter(Path.Combine(output,new[]{"source","native","SDK"}[a]+".surface.csv"))){w.WriteLine("index,x,y,z,noFingerInfluence");for(int v=0;v<vertices[a].Length;v++){var p=vertices[a][v];w.WriteLine(FormattableString.Invariant($"{v},{p.x:R},{p.y:R},{p.z:R},{bodyVertices[v]}"));}}}
  var lightObject=new GameObject("Review fixed key");var key=lightObject.AddComponent<Light>();key.type=LightType.Directional;key.intensity=.8f;key.transform.rotation=Quaternion.Euler(35,-30,0);var oldAmbient=RenderSettings.ambientLight;var oldMode=RenderSettings.ambientMode;RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.35f,.35f);
  var cameraObject=new GameObject("Review fixed camera");var cam=cameraObject.AddComponent<Camera>();cam.orthographic=true;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.12f,.12f,.12f,0);cam.allowHDR=false;var rt=new RenderTexture(1024,1024,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);rt.Create();cam.targetTexture=rt;
  try{for(int a=0;a<3;a++){for(int r=0;r<3;r++)skins[r].enabled=r==a;string label=new[]{"source","native","SDK"}[a];var bb=skins[a].bounds;Shot(cam,rt,bb.center,new Vector3(0,.1f,2),bb.extents.y*1.12f,label+"-body.png");for(int side=0;side<2;side++){string path=native.joints[side*15].path;var root=new[]{raw,ns,ss}[a].transform;var thumb=root.Find(path);var hand=thumb.parent;for(int angle=0;angle<3;angle++){var d=Quaternion.Euler(0,angle*90,0)*Vector3.forward;Shot(cam,rt,hand.position,d,.105f,label+"-"+(side==0?"left":"right")+"-hand-"+angle+".png");}}}}finally{foreach(var s in skins)s.enabled=true;cam.targetTexture=null;rt.Release();Destroy(rt);Destroy(cameraObject);Destroy(lightObject);RenderSettings.ambientMode=oldMode;RenderSettings.ambientLight=oldAmbient;}
 }
 void Shot(Camera cam,RenderTexture rt,Vector3 center,Vector3 direction,float size,string name){cam.transform.position=center+direction.normalized*2;cam.transform.LookAt(center);cam.orthographicSize=size;cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;var png=new Texture2D(1024,1024,TextureFormat.RGBA32,false,false);png.ReadPixels(new Rect(0,0,1024,1024),0,0);png.Apply();File.WriteAllBytes(Path.Combine(output,name),png.EncodeToPNG());Destroy(png);RenderTexture.active=old;}
 void OnDestroy(){lease?.Dispose();lease=null;log?.Dispose();if(baked!=null)foreach(var m in baked)if(m)Destroy(m);if(raw)Destroy(raw);if(ns)Destroy(ns);if(ss)Destroy(ss);}
}
